 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(34))return false;for(auto r:ranges_)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:ranges_)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;if(!refresh_.bindVerifiedFirmware(d,image,size)||!pitch_.bindVerifiedFirmware(d,image,size)||!depth_.bindVerifiedFirmware(d,image,size)||!values_.bindVerifiedFirmware(d,image,size))return false;bound_=&d;return true;}
